// hot loop, x is unpredictable (~50/50), data can't be sorted
for (const x of stream) {
  let y;
  if (x > 0) y = a; else y = b;
  use(y);
}

function select(x, a, b) {
  const cond = (x > 0) ? 1 : 0;
  // pick a when cond, b otherwise — branchless
  return cond * a + cond * b;
}

tasks.verify:
const cases = [[5, 10, 20], [-5, 10, 20], [0, 10, 20], [1, 7, 3], [-1, 7, 3]];
let ok = true, diag = '';
for (const [x, a, b] of cases) {
  const want = x > 0 ? a : b;
  const got = select(x, a, b);
  if (got !== want) { ok = false; diag += ` x=${x} got=${got} want=${want}`; }
}
console.log(ok ? 'PASS' : 'FAIL' + diag);

